<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx:alpine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:8080/library/nginx:alpine</span></span>
